<script setup lang="ts">
import { onMounted, onUnmounted } from 'vue'; import AppShell from '@/components/AppShell.vue'; import StatCard from '@/components/StatCard.vue'; import StatusBadge from '@/components/StatusBadge.vue'; import EmptyState from '@/components/EmptyState.vue'; import { useEdgeStore } from '@/stores/edge'; import { formatLastSeen } from '@/utils/status'
const edge = useEdgeStore(); let timer: ReturnType<typeof setInterval> | undefined
async function refresh() { try { await edge.refresh() } catch { /* shell remains useful while offline */ } }
onMounted(() => { refresh(); timer = setInterval(refresh, 5000) }); onUnmounted(() => { if (timer) clearInterval(timer) })
</script>
<template><AppShell><template #title>概览</template><view class="stats"><StatCard label="节点总数" :value="edge.status?.nodes ?? '—'" /><StatCard label="在线节点" :value="edge.nodes.filter(n => n.status === 'online').length" accent="#55d6be" /><StatCard label="待授权" :value="edge.nodes.filter(n => n.status === 'pending').length" accent="#ffbd69" /><StatCard label="MQTT 代理" :value="edge.status?.broker ? '运行中' : '未启用'" :accent="edge.status?.broker ? '#55d6be' : '#75809a'" /></view><view v-if="edge.status?.upstream" class="upstream"><view><text class="section-label">上游连接</text><text class="upstream-endpoint">{{ edge.status.upstream.endpoint || '未配置' }}</text></view><text :class="edge.status.upstream.connected ? 'good' : 'warn'">{{ edge.status.upstream.connected ? '已连接' : '未连接' }}</text></view><view class="section-head"><text>节点列表</text><text class="refresh" @tap="refresh">↻</text></view><EmptyState v-if="!edge.nodes.length" text="暂无节点" /><view v-else class="list"><view v-for="node in edge.nodes" :key="node.nodeId" class="node"><view class="node-main"><text class="node-name">{{ node.nodeId }}</text><text class="node-meta">{{ node.host }}:{{ node.port }} · {{ node.tools?.length || 0 }} 个工具 · {{ formatLastSeen(node.lastSeen) }}</text></view><StatusBadge :status="node.status" /></view></view></AppShell></template>
<style scoped>.stats { display:grid; grid-template-columns:1fr 1fr; gap:18rpx; }.upstream { display:flex; justify-content:space-between; align-items:center; background:#101a2d; border:1rpx solid #1a2a43; border-radius:22rpx; padding:26rpx; margin-top:22rpx; }.section-label { display:block; color:#75809a; font-size:20rpx; }.upstream-endpoint { display:block; color:#edf5ff; font-size:23rpx; margin-top:8rpx; max-width:430rpx; overflow:hidden; text-overflow:ellipsis; white-space:nowrap; }.good { color:#55d6be; font-size:22rpx; }.warn { color:#ffbd69; font-size:22rpx; }.section-head { display:flex; justify-content:space-between; font-size:34rpx; font-weight:800; margin:42rpx 0 20rpx; }.refresh { color:#55d6be; font-size:32rpx; }.list { display:flex; flex-direction:column; gap:16rpx; }.node { display:flex; justify-content:space-between; align-items:center; gap:16rpx; padding:25rpx; border-radius:22rpx; background:#101a2d; border:1rpx solid #1a2a43; }.node-main { min-width:0; display:flex; flex-direction:column; gap:9rpx; }.node-name { font-size:27rpx; font-weight:700; }.node-meta { color:#75809a; font-size:20rpx; white-space:nowrap; overflow:hidden; text-overflow:ellipsis; }</style>
